examples.setupTemplate:
val snackbars = remember { SnackbarHostState() }
val scope = rememberCoroutineScope()
var undone by remember { mutableIntStateOf(0) }
val archive: () -> Unit = {
    scope.launch {
        val result = snackbars.showMonarchSnackbar(
            message = {{toast.title}},
            tone = {{toast.tone|tone}},
            actionLabel = {{toast.action}},
            description = {{toast.description}},
            withDismissAction = true,
        )
        if (result == SnackbarResult.ActionPerformed) undone++
    }
}

examples.setup:
val snackbars = remember { SnackbarHostState() }
val scope = rememberCoroutineScope()
var undone by remember { mutableIntStateOf(0) }
val archive: () -> Unit = {
    scope.launch {
        val result = snackbars.showMonarchSnackbar(
            message = "Ticket archived",
            tone = MonarchTone.Success,
            actionLabel = "Undo",
            description = "You can undo this.",
            withDismissAction = true,
        )
        if (result == SnackbarResult.ActionPerformed) undone++
    }
}

